<?php require_once '../functions.php'; require_admin(); $title='CRUD Kategori';$edit=(int)($_GET['edit']??0);$row=null;if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='delete'){$s=$koneksi->prepare('DELETE FROM kategori WHERE id_kategori=?');$s->bind_param('i',$id);$s->execute();flash('success','Kategori dihapus.');redirect('kategori.php');}$name=trim($_POST['nama_kategori']??'');if($id){$s=$koneksi->prepare('UPDATE kategori SET nama_kategori=? WHERE id_kategori=?');$s->bind_param('si',$name,$id);}else{$s=$koneksi->prepare('INSERT INTO kategori(nama_kategori) VALUES(?)');$s->bind_param('s',$name);}$s->execute();flash('success','Kategori disimpan.');redirect('kategori.php');}if($edit){$s=$koneksi->prepare('SELECT * FROM kategori WHERE id_kategori=?');$s->bind_param('i',$edit);$s->execute();$row=$s->get_result()->fetch_assoc();}$list=$koneksi->query('SELECT k.*,COUNT(p.id_produk) jumlah_produk FROM kategori k LEFT JOIN produk p ON p.id_kategori=k.id_kategori GROUP BY k.id_kategori ORDER BY k.id_kategori DESC');include 'header.php'; ?>
<div class="container"><div class="section-head"><h1>CRUD Kategori</h1><a class="btn outline" href="kategori.php">+ Kategori Baru</a></div><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$row['id_kategori']??0?>"><input type="hidden" name="action" value="save"><label>Nama Kategori</label><input name="nama_kategori" value="<?=e($row['nama_kategori']??'')?>" required><button class="btn">Simpan</button><?php if($row):?><a class="btn outline" href="kategori.php">Batal</a><?php endif;?></form></div><div class="table-wrap"><table><tr><th>ID</th><th>Nama</th><th>Produk</th><th>Aksi</th></tr><?php while($r=$list->fetch_assoc()):?><tr><td><?=$r['id_kategori']?></td><td><?=e($r['nama_kategori'])?></td><td><?=$r['jumlah_produk']?></td><td><a href="?edit=<?=$r['id_kategori']?>">Edit</a><form method="post" class="inline" onsubmit="return confirm('Hapus kategori ini?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id_kategori']?>"><button class="link-danger">Hapus</button></form></td></tr><?php endwhile;?></table></div></div><?php include '../footer.php'; ?>
